-- ============================================
-- LUMA — Thème 15 : MOYEN 2/3 x4 — Une rencontre avec un Londonien dans un pub
-- ============================================


update scenarios set content = '{"characters": {"local": "le Londonien"}, "start_node": "n1", "nodes": {"n1": {"speaker": "local", "text": "Mind if I sit here? Bit crowded tonight.", "text_fr": "Ça vous dérange si je m''assois là ? Un peu bondé ce soir.", "choices": [{"text": "Not at all, please join! I''m actually a tourist, first time in London.", "text_fr": "Pas du tout, je vous en prie ! Je suis en fait touriste, première fois à Londres.", "next": "n2"}, {"text": "Go ahead! I could use some local recommendations, actually.", "text_fr": "Allez-y ! J''aurais bien besoin de recommandations locales, en fait.", "next": "n2b"}]}, "n2": {"speaker": "local", "text": "Ah, welcome then! What''s caught your eye so far?", "text_fr": "Ah, bienvenue alors ! Qu''est-ce qui vous a marqué jusqu''ici ?", "choices": [{"text": "The architecture, honestly. Everything feels so historic.", "text_fr": "L''architecture, honnêtement. Tout semble tellement historique.", "next": "n3"}]}, "n2b": {"speaker": "local", "text": "Happy to help! What kind of things are you into?", "text_fr": "Content d''aider ! Vous aimez quel genre de choses ?", "choices": [{"text": "Good food and hidden gems, not just the touristy spots.", "text_fr": "Bonne nourriture et pépites cachées, pas juste les endroits touristiques.", "next": "n3"}]}, "n3": {"speaker": "local", "text": "Then you have to check out Borough Market, way better than the usual tourist traps.", "text_fr": "Alors vous devez aller voir Borough Market, bien mieux que les pièges à touristes habituels.", "choices": [{"text": "I''ll definitely add that to my list, thank you!", "text_fr": "Je vais définitivement ajouter ça à ma liste, merci !", "next": "n4"}]}, "n4": {"speaker": "local", "text": "Also, skip the overpriced places near Big Ben — locals eat elsewhere.", "text_fr": "Aussi, évitez les endroits trop chers près de Big Ben — les locaux mangent ailleurs.", "choices": [{"text": "Where do locals usually go for a good meal then?", "text_fr": "Où les locaux vont-ils habituellement pour un bon repas alors ?", "next": "n5"}]}, "n5": {"speaker": "local", "text": "Honestly, little neighborhood spots in areas like Shoreditch, less flashy but way better food.", "text_fr": "Honnêtement, des petits coins de quartier dans des zones comme Shoreditch, moins tape-à-l''œil mais bien meilleure nourriture.", "choices": [{"text": "I love getting these kinds of insider tips, thank you so much.", "text_fr": "J''adore avoir ce genre de conseils d''initié, merci beaucoup.", "next": "n6"}]}, "n6": {"speaker": "local", "text": "Of course! It''s always nice meeting travelers who actually want the real experience.", "text_fr": "Bien sûr ! C''est toujours sympa de rencontrer des voyageurs qui veulent vraiment la vraie expérience.", "choices": [{"text": "That''s exactly what I''m hoping for on this trip.", "text_fr": "C''est exactement ce que j''espère pour ce voyage.", "next": "n7"}]}, "n7": {"speaker": "local", "text": "Well, cheers to that then! Enjoy the rest of your stay, truly.", "text_fr": "Bon, santé à ça alors ! Profitez vraiment du reste de votre séjour.", "choices": [{"text": "Cheers! Thank you for such a genuine conversation tonight.", "text_fr": "Santé ! Merci pour une conversation si sincère ce soir.", "next": "end_local"}]}, "end_local": {"speaker": "local", "text": "Anytime! London''s better when shared with curious visitors like you.", "text_fr": "Avec plaisir ! Londres est meilleure quand partagée avec des visiteurs curieux comme vous.", "end": true, "ending_label": "Une vraie rencontre locale au pub 🍺🇬🇧"}}}'::jsonb, is_playable = true
where title = 'Une rencontre avec un Londonien dans un pub'
  and theme_id = (select id from scenario_themes where position = 15 and language_id = (select id from languages where code = 'en'));
